from functools import lru_cache

def main():
    import sys
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    @lru_cache(maxsize=None)
    def dfs(current):
        max_removals = 0
        for i in range(len(current)):
            c = current[i]
            prev_char = chr(ord(c) - 1)
            left_ok = False
            right_ok = False
            if i > 0 and current[i-1] == prev_char:
                left_ok = True
            if i < len(current)-1 and current[i+1] == prev_char:
                right_ok = True
            if left_ok or right_ok:
                new_str = current[:i] + current[i+1:]
                res = 1 + dfs(new_str)
                if res > max_removals:
                    max_removals = res
        return max_removals

    print(dfs(s))

if __name__ == "__main__":
    main()
